/**
 * Jumia Egypt catalog adapter.
 *
 * The snapshot in `jumia-products.js` is generated by
 * `scripts/jumia-crawl.mjs`. Jumia rows are outbound affiliate items: they
 * are shown in BudoQ, but checkout happens on Jumia. Each product URL is
 * wrapped in the JForce Adjust deep-link template so the affiliate label is
 * attached without calling the JForce API per product.
 *
 * Set JFORCE_CASID in the environment to use a different consultant id.
 */

import { JUMIA_META, JUMIA_PRODUCTS } from "./jumia-products.js";

const DEFAULT_CASID = "e9131e9a-26f7-4c11-991f-9e4c6f987246";
const ADJUST_NETWORK_TOKEN = "1hao9f64_1heefw7z";
const ADJUST_CAMPAIGN = "JF_Affiliate_EG";
const JUMIA_HOST = "https://www.jumia.com.eg";

function consultantId() {
  return String(process.env.JFORCE_CASID || DEFAULT_CASID).trim();
}

/**
 * Wraps a Jumia URL in the same Adjust template the JForce dashboard
 * generates. Tested against product, category and search URLs.
 */
export function buildAffiliateUrl(target) {
  const raw = String(target || "").trim();
  if (!raw) return "";
  const destination = /^https?:\/\//i.test(raw)
    ? raw
    : JUMIA_HOST + (raw.startsWith("/") ? raw : "/" + raw);

  const label = `casid*${consultantId()}^type*jforce`;
  const separator = destination.includes("?") ? "&" : "?";
  const redirect =
    destination +
    separator +
    "utm_source=JFORCE" +
    "&utm_medium=JF_Affiliate" +
    "&utm_campaign=" +
    ADJUST_CAMPAIGN +
    "&adj_label=" +
    label;

  return (
    "https://aal4.adj.st/?adjust_deeplink=" +
    "jumia%3a%2f%2feg%3fadj_label%3d" +
    encodeURIComponent(label) +
    "&adjust_t=" +
    ADJUST_NETWORK_TOKEN +
    "&adjust_campaign=" +
    ADJUST_CAMPAIGN +
    "&adjust_redirect=" +
    encodeURIComponent(redirect)
  );
}

/**
 * Some early snapshots were produced from a mis-decoded HTML page, which
 * left control characters in the category. Never show those to a shopper.
 */
function cleanCategory(value) {
  const text = String(value || "").trim();
  if (!text) return "منتجات جوميا";
  const hasArabic = /[\u0600-\u06FF]/.test(text);
  // eslint-disable-next-line no-control-regex
  if (/[\u0000-\u001f\u007f\ufffd]/.test(text)) return "منتجات جوميا";
  // A category that is neither Arabic nor plain ASCII is usually a
  // mis-decoded page, so fall back instead of showing mojibake.
  if (!hasArabic && !/^[\x20-\x7e]*$/.test(text)) return "منتجات جوميا";
  return text;
}

const JUMIA_DESCRIPTION =
  "يُباع هذا المنتج عبر جوميا مصر. السعر والصور والبيانات معروضة من جوميا، " +
  "وإتمام الشراء والدفع والتوصيل يتم من خلال صفحة المنتج على جوميا.";

const JUMIA_HIGHLIGHTS = [
  "يُباع عبر جوميا مصر",
  "الدفع والتوصيل عبر جوميا",
  "السعر المعروض بالجنيه المصري",
];

let cachedRows = null;

/**
 * Returns catalog-shaped rows ready for api/_lib/catalog.js.
 * Built once per serverless instance because the snapshot is static.
 */
export function getJumiaRawRows() {
  if (cachedRows) return cachedRows;
  const generatedAt = JUMIA_META && JUMIA_META.generated_at
    ? JUMIA_META.generated_at
    : new Date().toISOString();

  cachedRows = JUMIA_PRODUCTS.map((product) => {
    if (!product || !product.id || !product.name || !product.url) return null;
    const category = cleanCategory(product.category);
    return {
      id: product.id,
      name: product.name,
      category,
      brand: product.brand || "",
      price: Number(product.price) || 0,
      original_price: Number(product.original_price) || 0,
      image: product.image || "",
      description: JUMIA_DESCRIPTION,
      highlights: JUMIA_HIGHLIGHTS,
      available_countries: ["EG"],
      stock: 99,
      stock_status: "in_stock",
      source: "jumia",
      external_url: buildAffiliateUrl(product.url),
      affiliate_source: "jforce",
      rating: Number(product.rating) || 0,
      reviewCount: Number(product.reviews) || 0,
      created_at: generatedAt,
    };
  }).filter(Boolean);

  return cachedRows;
}

export function getJumiaMeta() {
  return {
    ...JUMIA_META,
    count: JUMIA_PRODUCTS.length,
  };
}